// Competition-first guild experience. Trading and copy execution remain explicitly simulated.
paths.copy='M8 8h12v13H8z M4 16H2V2h12v3';paths.pause='M8 5v14M16 5v14';paths.chevron='m9 5 7 7-7 7';paths.lock='M5 10h14v11H5z M8 10V6a4 4 0 0 1 8 0v4';paths.wallet='M3 6h17v15H3V6 M3 6V3h14v3 M16 12h5v5h-5z';paths.info='M12 11v6 M12 7h.01 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0';
state.copyPlans=state.copyPlans||[];state.seasonEntries=state.seasonEntries||{};state.chatRead=state.chatRead||{};
const competition={name:'Guild Open',edition:'01',label:'SEASON 01',stage:'in-progress',volume:1368000000,cutoff:'Roster snapshot at entry',remaining:'12d 08h',sample:true};
const captains=[{id:'satoshi',guild:'unisat',name:'SatoshiWave',handle:'THE STRATEGIST',style:'BTC / ETH · Swing',roi:28.4,drawdown:12.8,winRate:64.2,trades:148,copiers:326,days:186,risk:'Moderate',description:'Patient entries. A defined risk budget. A focused approach to the major markets.',color:'blue'},{id:'vector',guild:'stellar',name:'Vector Prime',handle:'THE SYSTEMATIC MIND',style:'Multi-market · Systematic',roi:19.7,drawdown:8.6,winRate:58.9,trades:236,copiers:218,days:242,risk:'Moderate',description:'A systematic process built around consistency, position sizing and clear invalidation.',color:'silver'},{id:'alpha',guild:'alpha',name:'Alpha Zero',handle:'THE MOMENTUM READER',style:'Majors · Momentum',roi:42.6,drawdown:24.3,winRate:55.4,trades:312,copiers:187,days:124,risk:'High',description:'An active momentum style with higher volatility and wider drawdowns.',color:'gold'}];
const seasonUI={metric:'volume',stage:'standings',leaderSort:'balanced',leaderSearch:'',leaderFilter:'all',chatOpen:false,chatGuild:null,chatMembers:false,chatDrafts:{},chatReturnFocus:null};let copyStep=1,copyDraft=null;
const leaderById=id=>captains.find(x=>x.id===id);const numberCompact=v=>v>=1e9?'$'+(v/1e9).toFixed(2)+'B':v>=1e6?'$'+(v/1e6).toFixed(2)+'M':v>=1e3?'$'+(v/1e3).toFixed(1)+'K':'$'+Number(v).toFixed(2);
const seasonVolume=g=>Math.round(g.volume*1e8);const myPreview=()=>routeQuery.get('preview')==='1';
function progressPill(kind,text){return `<span class="status-pill ${kind}"><i></i>${text}</span>`}
function guildRank(g,metric='volume'){return guilds().sort((a,b)=>metric==='efficiency'?seasonVolume(b)/Math.max(1,b.members)-seasonVolume(a)/Math.max(1,a.members):metric==='participation'?b.activity-a.activity:seasonVolume(b)-seasonVolume(a)).findIndex(x=>x.id===g.id)+1}
function guildStatus(g){return state.seasonEntries[g.id]?'Demo entry confirmed':g.isNew?'Not entered':'Sample entrant'}
function seasonRankRows(limit=0){const metric=seasonUI.metric;const all=guilds().sort((a,b)=>metric==='efficiency'?seasonVolume(b)/Math.max(1,b.members)-seasonVolume(a)/Math.max(1,a.members):metric==='participation'?b.activity-a.activity:seasonVolume(b)-seasonVolume(a));const arr=limit?all.slice(0,limit):all.filter(g=>g.name.toLowerCase().includes(ui.rankQuery.toLowerCase()));return arr.map((g,i)=>`<tr class="${state.membership?.id===g.id?'my-standing':''}"><td><span class="rank-glyph rank-${i+1}">${String(all.findIndex(x=>x.id===g.id)+1).padStart(2,'0')}</span></td><td><a class="table-guild" href="#/guild/${g.id}"><img src="${emblem(g)}" alt=""><span>${escapeHtml(g.name)}${state.membership?.id===g.id?'<b class="you-label">YOUR GUILD</b>':''}<small>${g.isNew?'New trading circle':g.tier+' community'} · ${g.members.toLocaleString()} members</small></span></a></td><td class="season-volume">${metric==='participation'?g.activity+'%':metric==='efficiency'?numberCompact(seasonVolume(g)/Math.max(1,g.members)):numberCompact(seasonVolume(g))}</td><td class="season-trend">${g.isNew?'—':'+ '+(i===0?'12.4':i===1?'8.1':'6.7')+'%'}</td><td>${link('guild/'+g.id,'Explore '+arrow(),'row-link')}</td></tr>`).join('')||'<tr><td colspan="5" class="table-empty">No guilds match your search.</td></tr>'}
function primaryRankTable(limit=0){const metric=seasonUI.metric;return `<div class="season-table-wrap"><table class="season-table"><thead><tr><th>RANK</th><th>GUILD</th><th>${metric==='volume'?'SEASON VOLUME':metric==='efficiency'?'VOLUME / MEMBER':'PARTICIPATION'}</th><th>ILLUSTRATIVE TREND</th><th></th></tr></thead><tbody id="season-standings">${seasonRankRows(limit)}</tbody></table></div>`}
function metricTabs(){return `<div class="metric-tabs" role="group" aria-label="Ranking metric">${[['volume','Total volume'],['efficiency','Per member'],['participation','Participation']].map(([id,label])=>`<button data-season-metric="${id}" aria-pressed="${seasonUI.metric===id}" class="${seasonUI.metric===id?'selected':''}">${label}</button>`).join('')}</div>`}
function seasonStrip(){return `<div class="season-strip"><span>${icon('trophy')} GUILD OPEN <b>01</b></span><div>${progressPill('blue','IN-PROGRESS PREVIEW')}<span>All standings and times are illustrative</span></div>${link('competition','Competition hub '+arrow())}</div>`}
drawNav=function(section){const items=[['','Guild Season','trophy'],['rankings','Rankings','chart'],['discover','Find a Guild','search'],['leaders','Guild Leaders','shield'],['my-guild','My Guild','shield']];$('#guild-navigation').innerHTML=`<div class="guild-subnav"><div class="subnav-links">${items.map(([p,t,ic])=>`<a href="#/${p}" ${(section===p||section==='competition'&&p===''||section==='guild'&&p==='discover')?'class="current" aria-current="page"':''}>${icon(ic)}<span>${t}</span></a>`).join('')}</div><button class="subnav-create" data-action="create">＋ <span>Create Guild</span></button></div>`};
function captainCard(c){const g=guildById(c.guild);return `<article class="captain-card"><div class="captain-head"><span class="captain-avatar ${c.color}">${c.name.slice(0,1)}<i>${icon('shield')}</i></span><div><span class="micro-label">GUILD LEADER</span><h3>${escapeHtml(c.name)}</h3><a href="#/guild/${g.id}"><img src="${emblem(g)}" alt="">${escapeHtml(g.name)} ${arrow()}</a></div><span class="risk-label ${c.risk==='High'?'high':''}">${c.risk} risk</span></div><p>${c.style}</p><div class="captain-performance"><div><small>30D RETURN · SAMPLE</small><strong>+${c.roi.toFixed(1)}<em>%</em></strong></div><svg viewBox="0 0 120 45" aria-label="Illustrative return curve" role="img"><path d="M1 39 13 34 23 36 35 26 46 30 58 18 69 24 81 12 92 16 105 8 119 5"/></svg></div><div class="captain-facts"><div><span>Max. drawdown</span><strong>${c.drawdown}%</strong></div><div><span>Trading history</span><strong>${c.days} days</strong></div><div><span>Guild copiers · sample</span><strong>${c.copiers}</strong></div></div><div class="captain-card-foot">${link('leaders/'+c.id,'View performance '+arrow(),'text-button')}${link('guild/'+g.id,'Explore guild '+arrow(),'secondary button')}</div></article>`}
function seasonHome(){const ctx=memberContext();return `${seasonStrip()}<section class="season-hero"><div class="season-hero-art" role="img" aria-label="Equal guild emblems entering one shared circular trading competition arena"></div><div class="season-hero-shade"></div><div class="season-hero-content"><div class="page-eyebrow"><i></i> XOX GUILDS · TRADE AS A TEAM.</div><h1>TRADE TOGETHER.<br><span>CLIMB TOGETHER.</span></h1><p>Join a guild. Contribute your trades.<br>Compete together on one shared leaderboard.</p><div class="season-hero-buttons">${link(ctx.g?'my-guild'+previewSuffix(ctx.preview):'discover',ctx.g?'Open my guild '+arrow():'Find your guild '+arrow(),'primary button')}${link('competition','Explore the competition '+arrow(),'secondary button')}</div><div class="hero-proof"><span>${icon('users')} Built for teams</span><span>${icon('chart')} Driven by contribution</span><span>${icon('trophy')} Defined by progress</span></div></div><div class="hero-art-label"><span>THE GUILD OPEN</span><strong>01</strong><small>MANY GUILDS. ONE ARENA.</small></div></section><div class="season-home-metrics"><div><small>THE FIELD</small><strong>${guilds().length}<em>guilds</em></strong></div><div><small>TEAM TRADING VOLUME</small><strong>${numberCompact(guilds().reduce((a,g)=>a+seasonVolume(g),0))}</strong></div><div><small>THE NEXT CHECKPOINT</small><strong>12d<em>08h · sample</em></strong></div><div><small>YOUR NEXT MOVE</small><strong>${ctx.g?'Contribute together':'Find your people'}</strong></div></div><div class="season-data-caption">${icon('info')} Interactive competition preview. No live event, copy trading or reward execution is connected.</div>${ctx.g?nextAction(ctx.g,ctx.preview):`<div class="getting-started"><div><span>01</span><strong>Find your guild</strong><small>A circle that shares your ambition.</small></div><i></i><div><span>02</span><strong>Enter the arena</strong><small>A shared place on the standings.</small></div><i></i><div><span>03</span><strong>Make your mark</strong><small>Contribute, climb and grow.</small></div></div>`}<section class="home-rank-section"><div class="home-section-header"><div><span class="page-eyebrow">THE COLLECTIVE CHASE</span><h2>Different teams.<br><span>One leaderboard.</span></h2></div>${link('rankings','Explore all standings '+arrow(),'secondary button')}</div><div class="workspace-panel season-standings-panel"><div class="season-panel-top"><div>${icon('trophy')}<strong>Guild Open standings</strong><span class="demo-chip">DEMO SEASON</span></div>${metricTabs()}</div>${primaryRankTable(5)}<div class="table-foot"><span>Compare volume, contribution per member and participation.</span><span>Illustrative rankings</span></div></div></section><section class="home-captains"><div class="home-section-header"><div><span class="page-eyebrow">MEET THE GUILD LEADERSHIP</span><h2>Meet the minds<br><span>behind the guilds.</span></h2></div><div><p>See the results. Understand the team behind them.</p>${link('leaders','Meet the guild leaders '+arrow(),'text-button')}</div></div><div class="captain-grid">${captains.map(captainCard).join('')}</div><p class="copy-risk-caption">Illustrative performance. Past returns do not predict future results. Copy trading can lose capital.</p></section><section class="battle-secondary-banner"><div class="battle-banner-symbol">${icon('swords')}</div><div><span class="page-eyebrow">A DIFFERENT KIND OF CHALLENGE</span><h2>Two guilds. <span>A step forward.</span></h2><p>Head-to-head battles are your team’s progression challenges, alongside the main season.</p></div>${link('arena','Explore Guild Battle '+arrow(),'secondary button')}</section><section class="home-founding"><span class="page-eyebrow">A SHARED VISION NEEDS A HOME.</span><h2>Bring your people.<br><span>Build your legacy.</span></h2><p>Start a guild, set the tone and create your place in the competition.</p><button class="primary" data-action="create">Create your guild ${arrow()}</button></section>${footer()}`}
function nextAction(g,preview){const entered=!!state.seasonEntries[g.id]||!g.isNew;return `<div class="next-action"><span class="next-action-icon">${icon(entered?'chart':'trophy')}</span><div><small>YOUR NEXT MOVE</small><h3>${entered?'Your team is in the arena.':'Your team is ready for its first chapter.'}</h3><p>${entered?'Follow your standing, see the gap and make your contribution.':'Review the competition and confirm your demo entry.'}</p></div>${link(entered?'my-guild'+previewSuffix(preview):'competition/entry'+previewSuffix(preview),entered?'Open team dashboard '+arrow():'Review competition entry '+arrow(),'primary button')}</div>`}
rankingPage=function(){return breadcrumb('Season standings')+heading('THE GUILD OPEN · 01','MANY TEAMS.<br><span>ONE COLLECTIVE CHASE.</span>','Volume is one perspective. Explore efficiency and participation alongside the main standings.',`<div class="rank-season-detail">${progressPill('blue','IN-PROGRESS PREVIEW')}<span>12d 08h to the sample finish</span></div>`)+`<div class="rank-top-three">${[...baseGuilds].sort((a,b)=>b.volume-a.volume).slice(0,3).map((g,i)=>`<a href="#/guild/${g.id}"><span class="rank-podium-position">0${i+1}</span><img src="${emblem(g)}" alt=""><div><small>${i===0?'SETTING THE PACE':i===1?'CLOSING THE GAP':'IN THE CHASE'}</small><h2>${g.name}</h2><span>${g.members} members · ${g.tier}</span></div><strong>${numberCompact(seasonVolume(g))}<small>SEASON VOLUME</small></strong></a>`).join('')}</div><div class="workspace-panel season-standings-panel"><div class="season-panel-top"><div><strong>Guild standings</strong><span class="demo-chip">DEMO</span></div>${metricTabs()}</div><div class="season-rank-tools"><label class="search">${icon('search')}<input type="search" id="season-rank-search" value="${escapeHtml(ui.rankQuery)}" placeholder="Find your guild…" aria-label="Search season standings"></label><span>Comparative views · Scoring parameters remain adjustable</span></div>${primaryRankTable()}<div class="table-foot"><span id="season-result-count">${guilds().length} guilds in this preview</span><span>Sample checkpoint · No live data feed</span></div></div><div class="fair-ranking-note">${icon('shield')}<div><h3>A bigger team isn’t the only story.</h3><p>Per-member volume and participation provide additional context. These views are illustrative; final competition rules and scoring will be designed separately.</p></div>${link('competition/rules','Explore competition rules '+arrow(),'text-button')}</div>`};
// The legacy router invokes this after rendering rankings; the new table updates itself.
const previousUpdateRanks=updateRanks;updateRanks=function(){if($('#full-rank-rows'))previousUpdateRanks()};
function competitionTabs(tab){return `<div class="page-tabs competition-tabs">${[['overview','Competition'],['rules','How it works'],['results','Results preview']].map(([id,t])=>link('competition'+(id==='overview'?'':'/'+id),t,id===tab?'selected':'')).join('')}<span>GUILD OPEN 01 · DEMO EXPERIENCE</span></div>`}
function competitionPage(tab='overview'){if(tab==='entry')return competitionEntry();return breadcrumb('Competition hub')+heading('A CLEAR FIELD. A SHARED AMBITION.','THE GUILD<br><span>OPEN.</span>','One season for every guild. A clear path from team entry to final results.',`<div class="competition-edition">01<small>SEASON PREVIEW</small></div>`)+`<div class="competition-phase-track">${[['01','Prepare','Find your team'],['02','Enter','Confirm the guild'],['03','Compete','Contribute & climb'],['04','Review','Verify results']].map(([n,t,p],i)=>`<div class="${i===2?'active':''}"><span>${n}</span><div><strong>${t}</strong><small>${p}</small></div></div>`).join('')}</div>${competitionTabs(tab)}${tab==='rules'?competitionRules():tab==='results'?competitionResults():competitionOverview()}`}
function competitionOverview(){const ctx=memberContext();return `<div class="competition-overview-grid"><section class="competition-brief"><span class="page-eyebrow">YOUR TEAM’S PLACE IN THE FIELD</span><h2>Every guild has<br><span>a place in the chase.</span></h2><p>The Guild Open brings teams together around contribution and progress. The main leaderboard is the shared arena; head-to-head battles are a separate path to guild progression.</p><div class="competition-brief-facts"><div><span>Primary competition</span><strong>Multi-guild standings</strong></div><div><span>Additional perspectives</span><strong>Per-member volume · Participation</strong></div><div><span>Team size</span><strong>No member limit</strong></div><div><span>Current view</span><strong>In-progress design preview</strong></div></div>${ctx.g?link('competition/entry'+previewSuffix(ctx.preview),'Review team entry '+arrow(),'primary button'):link('discover','Find your guild '+arrow(),'primary button')}</section><aside class="competition-art-card"><div class="competition-art-shields"><img src="assets/unisat.webp" alt=""><img src="assets/stellar.webp" alt=""><img src="assets/alpha.webp" alt=""></div><span class="page-eyebrow">ONE FIELD. MANY PERSPECTIVES.</span><h2>Made for your<br>trading circle.</h2><p>Shared standing.<br>Personal contribution.<br>Clear results.</p></aside></div><div class="competition-details-grid">${[['trophy','Stand together','A shared season position gives every team a clear next target.'],['chart','Know your contribution','See your personal activity and how it relates to the guild’s progress.'],['shield','Finish with clarity','Provisional results, review and reward details belong in the same journey.']].map(([ic,t,p])=>`<article>${icon(ic)}<h3>${t}</h3><p>${p}</p></article>`).join('')}</div><div class="workspace-panel competition-open-questions">${sectionTitle('Clear before the first trade','Competition design checkpoints')}<div>${[['Eligibility','Account and trade eligibility rules'],['Roster & transfers','When contributions attach to a guild'],['Scoring','Eligible volume, exclusions and ranking criteria'],['Settlement','Result review and reward allocation']].map(([t,p])=>`<div><span>${icon('check')}</span><strong>${t}</strong><p>${p}</p><small>PARAMETERS TO BE DESIGNED</small></div>`).join('')}</div></div>`}
function competitionRules(){return `<div class="content-grid"><section class="workspace-panel">${sectionTitle('A simple path through the season','Flow first. Final parameters follow.')}<div class="format-list">${[['01','Find or build your trading circle','Explore guilds, meet their leaders and choose the community you want to participate with.'],['02','Review the team entry','Guild leadership reviews the event summary and the team roster concept before confirming a local demo entry.'],['03','Contribute and follow the chase','The dashboard connects guild standings, the gap to the next team and individual participation.'],['04','Review the final result','Provisional results lead into a verification state, followed by a clear team result and individual reward breakdown.']].map(([n,t,p])=>`<div><span>${n}</span><div><h3>${t}</h3><p>${p}</p></div></div>`).join('')}</div></section><aside class="workspace-panel rule-summary">${sectionTitle('Rules that need one clear answer')}<div class="rule-state"><span>Eligible trades & exclusions</span><strong>To be designed</strong></div><div class="rule-state"><span>Transfer / roster attribution</span><strong>To be designed</strong></div><div class="rule-state"><span>Copy-trade volume attribution</span><strong>To be designed</strong></div><div class="rule-state"><span>Reward calculation</span><strong>To be designed</strong></div><div class="notice">This prototype demonstrates the journey. It does not enroll anyone into a live competition or establish final rules.</div></aside></div>`}
function competitionEntry(){const ctx=memberContext(),g=ctx.g;if(!g)return breadcrumb('Competition entry')+`<div class="page-empty">${icon('users')}<h1>Your team comes first.</h1><p>Join or create a demo guild before reviewing team entry.</p>${link('discover','Find your guild '+arrow(),'primary button')}</div>`;const entry=state.seasonEntries[g.id];const owner=!ctx.preview&&state.membership?.role==='owner';return breadcrumb(`${link('competition','Competition hub')}<span>/</span>Team entry`)+heading('A SHARED COMMITMENT','YOUR TEAM.<br><span>YOUR PLACE IN THE FIELD.</span>','Review the competition and the team taking part.')+`<div class="entry-review-layout"><section class="workspace-panel entry-review-panel">${sectionTitle('Guild Open · Team entry',entry?'Local demo entry saved':'A clear review before your team enters')}<div class="entry-guild-identity"><img src="${emblem(g)}" alt=""><div><h2>${escapeHtml(g.name)}</h2><p>${g.members.toLocaleString()} members · No member limit</p></div>${progressPill(entry?'green':'blue',entry?'DEMO ENTRY CONFIRMED':g.isNew?'READY TO REVIEW':'SAMPLE ENTRANT')}</div><div class="entry-review-facts"><div><span>Competition</span><strong>Guild Open 01</strong></div><div><span>Format</span><strong>Multi-guild leaderboard</strong></div><div><span>Entry reviewed by</span><strong>${escapeHtml(state.membership?.name||'Demo guild leader')}</strong></div><div><span>Roster attribution</span><strong>Review concept · Final policy pending</strong></div></div>${entry?`<div class="entry-confirmed-note">${icon('check')} Your local demo entry is saved. No live registration or roster lock has occurred.</div>`:owner?`<form id="season-entry-form" class="form" data-id="${g.id}"><label class="check"><input type="checkbox" required><span>I’ve reviewed the competition flow and understand that scoring, roster and transfer parameters are still to be designed.</span></label><label class="check"><input type="checkbox" required><span>I understand this is a local demo entry, not registration for a live event.</span></label><button class="primary" type="submit">Confirm demo team entry ${arrow()}</button></form>`:`<div class="notice">${ctx.preview?'This is a sample member view.':'Team entry is managed by the guild leader.'} Your personal demo membership remains unchanged.</div>`}</section><aside class="entry-team-preview">${icon('shield')}<h2>One guild.<br>A collective ambition.</h2><p>The entry step gives your team a clear beginning. The dashboard gives every member a clear next move.</p>${link('my-guild'+previewSuffix(ctx.preview),'Open team dashboard '+arrow(),'secondary button')}${link('competition/rules','Review the flow '+arrow(),'text-button')}</aside></div>`}
function competitionResults(){return `<div class="results-preview-notice">${icon('info')} POST-SEASON DESIGN PREVIEW · This is a sample end-of-season state, not the current result.</div><div class="results-stage-switch" role="group" aria-label="Result state preview">${[['standings','Provisional'],['review','Under review'],['final','Final result']].map(([id,t])=>`<button data-result-stage="${id}" aria-pressed="${seasonUI.stage===id}" class="${seasonUI.stage===id?'selected':''}">${t}</button>`).join('')}</div><section class="results-summary"><span class="results-trophy">${icon('trophy')}</span><span class="page-eyebrow">GUILD OPEN 01 · SAMPLE RESULT</span><h2>${seasonUI.stage==='review'?'Every contribution deserves a clear result.':seasonUI.stage==='final'?'A shared finish. A lasting legacy.':'The finish is a checkpoint.'}</h2><p>${seasonUI.stage==='review'?'Illustrative trades and standings are being reviewed in this state. No reward is available to claim.':seasonUI.stage==='final'?'This layout shows a final team result and personal breakdown. Reward terms and execution are not connected.':'Provisional standings come before verification. Final positions and reward details follow the review.'}</p>${progressPill(seasonUI.stage==='final'?'green':'blue',seasonUI.stage==='final'?'FINAL DESIGN PREVIEW':seasonUI.stage==='review'?'REVIEW STATE PREVIEW':'PROVISIONAL PREVIEW')}</section><div class="results-detail-cards"><div><small>SAMPLE GUILD POSITION</small><strong>#01</strong><span>UniSat · Illustrative standings</span></div><div><small>YOUR ELIGIBLE CONTRIBUTION</small><strong>—</strong><span>Pending production attribution rules</span></div><div><small>YOUR REWARD BREAKDOWN</small><strong>—</strong><span>No claimable funds in this prototype</span></div></div><div class="workspace-panel">${sectionTitle('A result you can understand','Team position, contribution attribution and reward details in one place')}<div class="result-breakdown"><div><span>Team performance</span><strong>Volume, rank and final status</strong></div><div><span>Individual participation</span><strong>Eligible activity and attribution</strong></div><div><span>Reward calculation</span><strong>Published rules and transparent amounts</strong></div><div><span>Settlement</span><strong>Verified status before any claim</strong></div></div></div>`}
function leadersPage(id){if(id)return captainProfile(id);return breadcrumb('Guild leaders')+heading('PUBLIC PERFORMANCE. SHARED GUILD IDENTITY.','MEET THE LEADERS.<br><span>FIND YOUR TRADING CIRCLE.</span>','View every guild leader’s performance. Leader copying is available only to members of that leader’s own guild.',`<div class="copy-design-marker">${icon('shield')} GUILD LEADERS<small>PUBLIC PERFORMANCE</small></div>`)+`<div class="leader-context-note">${icon('shield')}<div><strong>Open performance. Member-only copying.</strong><p>Anyone can view a leader’s results. Only members of the same guild can configure copying, from their guild workspace. Joining never turns it on automatically.</p></div>${link('my-guild/copy'+previewSuffix(myPreview()),'My demo copy plans '+arrow(),'secondary button')}</div><div class="leader-toolbar"><div class="page-filters">${[['all','All leaders'],['moderate','Moderate risk'],['guild','My guild leader']].map(([id,t])=>`<button data-leader-filter="${id}" class="${seasonUI.leaderFilter===id?'selected':''}">${t}</button>`).join('')}</div><label class="search">${icon('search')}<input type="search" id="leader-search" placeholder="Search leader or guild…" value="${escapeHtml(seasonUI.leaderSearch)}" aria-label="Search copy leaders"></label></div><div class="results-meta"><span id="leader-result-count"></span><span class="demo-chip">SAMPLE PERFORMANCE · UNVERIFIED</span></div><div class="captain-grid" id="leader-cards"></div><div class="copy-explainer">${[['chart','Understand the performance','Public results, drawdown and trading history help you understand the leader’s approach.'],['users','Find the right guild','Choose the team you want to be part of. Membership determines access to that guild leader’s copy feature.'],['shield','Choose within your guild','Members can opt in, set limits and manage their own leader-copy plan. Joining does not activate it.']].map(([ic,t,p])=>`<div>${icon(ic)}<h3>${t}</h3><p>${p}</p></div>`).join('')}</div><div class="copy-risk-note">${icon('info')} All performance shown is illustrative. Past returns do not predict future returns. Copy trading can lose capital; positions and slippage can differ from the leader.</div>`}
function updateLeaders(){const own=state.membership?.id;const filtered=captains.filter(c=>(seasonUI.leaderFilter==='all'||seasonUI.leaderFilter==='moderate'&&c.risk==='Moderate'||seasonUI.leaderFilter==='guild'&&c.guild===own)&&`${c.name} ${guildById(c.guild).name}`.toLowerCase().includes(seasonUI.leaderSearch.toLowerCase()));$('#leader-result-count').textContent=`${filtered.length} leader${filtered.length===1?'':'s'} to explore`;$('#leader-cards').innerHTML=filtered.length?filtered.map(captainCard).join(''):`<div class="page-empty">${icon('search')}<h2>${seasonUI.leaderFilter==='guild'?'No sample strategy for your guild yet.':'No leaders found.'}</h2><p>${seasonUI.leaderFilter==='guild'?'Explore the available sample leaders. Copy trading is a separate, optional decision.':'Try a different search or risk filter.'}</p><button class="secondary" data-reset-leaders>Explore all leaders</button></div>`}
function captainProfile(id){const c=leaderById(id);if(!c)return notFound();const g=guildById(c.guild);return breadcrumb(`${link('leaders','Guild leaders')}<span>/</span>${escapeHtml(c.name)}`)+`<section class="captain-profile-header"><div class="captain-profile-identity"><span class="captain-avatar large ${c.color}">${c.name.slice(0,1)}<i>${icon('shield')}</i></span><div><span class="page-eyebrow">GUILD LEADER · ${c.handle}</span><h1 tabindex="-1">${c.name}</h1><a href="#/guild/${g.id}"><img src="${emblem(g)}" alt="">${g.name} ${arrow()}</a><p>${c.description}</p></div></div><div><span class="risk-label ${c.risk==='High'?'high':''}">${c.risk} risk · Sample classification</span>${publicLeaderAccess(c)}</div></section><div class="leader-stat-grid"><div><small>30D RETURN · SAMPLE</small><strong class="return-positive">+${c.roi}%</strong></div><div><small>MAX. DRAWDOWN · SAMPLE</small><strong>${c.drawdown}%</strong></div><div><small>SAMPLE WIN RATE</small><strong>${c.winRate}%</strong></div><div><small>SAMPLE CLOSED TRADES</small><strong>${c.trades}</strong></div></div><div class="captain-profile-grid"><section class="workspace-panel">${sectionTitle('A strategy is more than a return','Illustrative curve · Not verified performance',pageTag)}${strategyCurve(c)}<div class="panel-footnote">Illustrative indexed equity, base 100. No production feed. The sample curve is not a projection.</div></section><aside class="workspace-panel strategy-context">${sectionTitle('Know the approach')}<div><span>Trading style</span><strong>${c.style}</strong></div><div><span>Sample history</span><strong>${c.days} days</strong></div><div><span>Guild copiers · sample</span><strong>${c.copiers}</strong></div><div><span>Performance basis</span><strong>Illustrative · Before fees</strong></div><p>Evaluate drawdown and position exposure alongside returns. A copied account may experience different entries, slippage and outcomes.</p></aside></div><section class="workspace-panel strategy-positions">${sectionTitle('Inside the strategy','Sample positions · Not trade instructions')}<div class="page-table-wrap"><table class="workspace-table"><thead><tr><th>PAIR</th><th>DIRECTION</th><th>STYLE</th><th>SAMPLE EXPOSURE</th><th>STATUS</th></tr></thead><tbody><tr><td>BTC / USDT</td><td><span class="position-side">Long</span></td><td>Major-market swing</td><td>55%</td><td>Illustrative position</td></tr><tr><td>ETH / USDT</td><td><span class="position-side">Long</span></td><td>Major-market swing</td><td>30%</td><td>Illustrative position</td></tr><tr><td>Unallocated</td><td>—</td><td>Risk reserve</td><td>15%</td><td>Illustrative allocation</td></tr></tbody></table></div></section><div class="copy-risk-note">${icon('info')} Returns and positions are sample data. Copy trading can lose capital. This prototype does not connect a wallet, open orders or guarantee matching the leader’s trades.</div>`}
function startCopy(id){const c=leaderById(id);if(!c)return;if(!canCopyGuildLeader(c)){showGuildCopyGate(c);return;}const existing=state.copyPlans.find(p=>p.leader===id&&p.status!=='stopped');if(existing){navigate('my-guild/copy');toast('You already have a demo plan for this leader.');return}copyStep=1;copyDraft={leader:id,allocation:'250',orderCap:'10',stopLoss:'20',leverage:'2',sizing:'proportional'};renderCopySetup()}
function captureCopyDraft(){const form=$('#copy-setup-form');if(!form)return;const f=new FormData(form);for(const k of ['allocation','orderCap','stopLoss','leverage','sizing'])if(f.has(k))copyDraft[k]=String(f.get(k))}
function renderCopySetup(){const c=leaderById(copyDraft.leader);if(!canCopyGuildLeader(c)){showGuildCopyGate(c);return;}const amount=Number(copyDraft.allocation),cap=Number(copyDraft.orderCap),stop=Number(copyDraft.stopLoss);open(`<div class="copy-setup"><div class="modal-eyebrow">YOUR CAPITAL. YOUR CHOICE.</div><h2>${copyStep===1?'Choose your allocation.':copyStep===2?'Set your boundaries.':'Review your demo plan.'}</h2><div class="copy-step-track">${['Allocate','Set limits','Confirm'].map((t,i)=>`<span class="${copyStep===i+1?'active':copyStep>i+1?'complete':''}">${i+1}<small>${t}</small></span>`).join('')}</div><div class="copy-target"><span class="captain-avatar ${c.color}">${c.name.slice(0,1)}</span><div><strong>${c.name}</strong><small>${guildById(c.guild).name} · Guild leader</small></div><span class="risk-label ${c.risk==='High'?'high':''}">${c.risk} risk</span></div><form id="copy-setup-form" class="form">${copyStep===1?`<label for="copy-allocation">Simulated allocation <span>USDT</span></label><input id="copy-allocation" name="allocation" type="number" min="1" max="1000000" step="0.01" required value="${escapeHtml(copyDraft.allocation)}"><div class="copy-allocation-presets">${[100,250,500,1000].map(v=>`<button type="button" data-copy-amount="${v}" class="${amount===v?'selected':''}">${v} USDT</button>`).join('')}</div><label for="copy-sizing">Position sizing concept</label><select id="copy-sizing" name="sizing"><option value="proportional" ${copyDraft.sizing==='proportional'?'selected':''}>Proportional within your allocation</option><option value="fixed" ${copyDraft.sizing==='fixed'?'selected':''}>Fixed allocation per new position</option></select><div class="copy-choice-note">${icon('lock')} New positions only. This demo does not open existing leader positions or connect your wallet.</div>`:copyStep===2?`<label for="copy-order-cap">Maximum allocation per position <span>% of plan allocation</span></label><input id="copy-order-cap" name="orderCap" type="number" min="1" max="100" step="1" required value="${escapeHtml(copyDraft.orderCap)}"><label for="copy-stop-loss">Plan loss threshold <span>% of initial allocation</span></label><input id="copy-stop-loss" name="stopLoss" type="number" min="1" max="100" step="1" required value="${escapeHtml(copyDraft.stopLoss)}"><label for="copy-leverage">Maximum leverage cap</label><select id="copy-leverage" name="leverage">${['1','2','3','5'].map(v=>`<option value="${v}" ${copyDraft.leverage===v?'selected':''}>${v}× cap</option>`).join('')}</select><div class="copy-choice-note">${icon('shield')} These are simulated plan limits. A production stop trigger cannot guarantee an execution price or eliminate losses.</div>`:`<div class="copy-review"><div><span>Simulated allocation</span><strong>${amount.toLocaleString()} USDT</strong></div><div><span>Position sizing</span><strong>${copyDraft.sizing==='fixed'?'Fixed allocation':'Proportional'}</strong></div><div><span>Maximum per position</span><strong>${(amount*cap/100).toFixed(2)} USDT · ${cap}%</strong></div><div><span>Plan loss threshold</span><strong>${(amount*stop/100).toFixed(2)} USDT · ${stop}%</strong></div><div><span>Leverage cap</span><strong>${copyDraft.leverage}×</strong></div><div><span>Position scope</span><strong>New positions only</strong></div></div><label class="check"><input name="riskAck" type="checkbox" required><span>I understand copy trading can lose capital, results can differ from the leader and past performance does not predict future returns.</span></label><label class="check"><input name="demoAck" type="checkbox" required><span>I understand this saves a simulated plan on this browser. No funds are allocated and no orders are opened.</span></label>`}<div class="modal-actions"><button class="secondary" type="button" ${copyStep>1?'data-copy-prev':'data-close-flow'}>${copyStep>1?'Back':'Cancel'}</button>${copyStep<3?'<button class="primary" type="button" data-copy-next>Continue '+arrow()+'</button>':'<button class="primary" type="submit">Create demo copy plan '+arrow()+'</button>'}</div></form></div>`)}
const priorMyGuildPage=myGuildPage;
myGuildPage=function(tab='overview',preview=false){if(tab==='copy')return copyPlansPage(preview);return priorMyGuildPage(tab,preview)};
dashboardTabs=function(tab,preview){return `<div class="page-tabs dashboard-tabs">${[['overview','Team dashboard'],['members','Members'],['missions','Missions'],['copy','My copy plans'],['settings','Settings']].map(([id,t])=>link('my-guild'+(id==='overview'?'':'/'+id)+previewSuffix(preview),t,id===tab?'selected':'')).join('')}</div>`};
const originalTeamDashboard=dashboardOverview;
dashboardOverview=function(g,preview){const all=(typeof worldGuilds==='function'&&communityById(g.id)?worldGuilds():guilds()).sort((a,b)=>seasonVolume(b)-seasonVolume(a)),rank=guildRank(g),above=rank>1?all[rank-2]:null;const gap=above?seasonVolume(above)-seasonVolume(g):0;const captain=captains.find(c=>c.guild===g.id);const entered=state.seasonEntries[g.id]||!g.isNew;return `<div class="team-season-heading"><div><span class="page-eyebrow">GUILD OPEN 01 · YOUR TEAM IN THE CHASE</span><h2>One standing.<br><span>Every contribution matters.</span></h2></div>${link('competition/entry'+previewSuffix(preview),entered?'Review team entry '+arrow():'Enter the demo season '+arrow(),'secondary button')}</div><div class="team-competition-stats"><div><small>GUILD POSITION</small><strong>#${String(rank).padStart(2,'0')}</strong><span>${guildStatus(g)}</span></div><div><small>TEAM SEASON VOLUME</small><strong>${numberCompact(seasonVolume(g))}</strong><span>Illustrative eligible activity</span></div><div><small>${above?'GAP TO '+above.name.toUpperCase():'YOUR TEAM’S POSITION'}</small><strong>${above?numberCompact(gap):'Setting the pace'}</strong><span>${above?'The next collective target':'Every contribution helps the team'}</span></div><div><small>YOUR CONTRIBUTION</small><strong>${preview?'$128.5K':'$0.00'}</strong><span>${preview?'Sample member profile':'No connected trading activity'}</span></div></div>${!entered?nextAction(g,preview):''}<div class="team-central-grid"><section class="workspace-panel team-season-chart">${sectionTitle('The season is a collective effort','Illustrative team trading activity',link('rankings','View the standings '+arrow(),'text-button'))}${teamSeasonCurve(g)}<div class="team-data-status"><span>${icon('clock')} Sample checkpoint · No live feed</span><button class="text-button" data-flow-trade>Trade to contribute ${arrow()}</button></div></section><aside class="team-captain-panel"><span class="page-eyebrow">THE PERSON BEHIND THE PERSPECTIVE</span>${captain?`<span class="captain-avatar ${captain.color}">${captain.name.slice(0,1)}</span><h3>${captain.name}</h3><span class="captain-role-label">YOUR GUILD LEADER</span><p>${captain.style}</p><div><span>Sample 30D return</span><strong>+${captain.roi}%</strong></div><div><span>Sample max. drawdown</span><strong>${captain.drawdown}%</strong></div>${link('leaders/'+captain.id,'View leader performance '+arrow(),'secondary button')}${!preview&&canCopyGuildLeader(captain)?`<button class="primary member-copy-entry" data-start-copy="${captain.id}">Copy your guild leader ${icon('copy')}</button>`:''}<small>${preview?'Member preview · Join this guild to use leader copying.':'Only your guild members can opt in. You choose the allocation and limits.'}</small>`:`<span class="captain-avatar">${escapeHtml((state.membership?.name||'L').slice(0,1))}</span><h3>${escapeHtml(state.membership?.name||'Guild leadership')}</h3><span class="captain-role-label">GUILD LEADER</span><p>Your team’s strategy starts with a shared direction.</p>${link('leaders','Meet the guild leaders '+arrow(),'secondary button')}<small>Leader performance and copy availability will appear here when a strategy is connected.</small>`}</aside></div><section class="team-progression-challenge"><div><span>${icon('swords')}</span><div><small>HEAD-TO-HEAD · GUILD PROGRESSION</small><h3>A challenge beyond the main standings.</h3><p>Two-guild battles are a separate journey toward the next guild chapter.</p></div></div>${link('arena'+previewSuffix(preview),'Explore the challenge '+arrow(),'secondary button')}</section><div id="dashboard-missions">${missionBoard(g,preview)}</div><div class="team-community-bar"><div>${icon('chat')}<span><strong>Your trading circle is one click away.</strong><small>Share an idea, coordinate a mission or catch up with the team.</small></span></div><button class="secondary" data-open-chat="${g.id}">Open guild chat ${arrow()}</button></div>`};
const previousArenaPage=arenaPage;
arenaPage=function(tab='overview'){return previousArenaPage(tab).replace("breadcrumb('Guild Battle')", "breadcrumb('Guild Battle')").replace('TRADE AS INDIVIDUALS. COMPETE AS ONE.','GUILD PROGRESSION · HEAD-TO-HEAD').replace('The match, the milestones and the people moving your guild forward.','A two-guild progression challenge alongside the main Guild Open standings. Battle outcomes and upgrade rules remain demonstration concepts.').replace('WEEKLY GUILD BATTLE','GUILD PROGRESSION CHALLENGE').replace('<div class="page-tabs">',`<div class="battle-context-link">${icon('trophy')} The main competition is the multi-guild Guild Open. ${link('rankings','Open season standings '+arrow(),'text-button')}</div><div class="page-tabs">`)};
featureLinks=function(g,preview){return `<div class="flow-feature-links">${link('rankings',`<span class="feature-orb">${icon('trophy')}</span><span><small>MULTI-GUILD SEASON</small><strong>Guild Open standings</strong></span>${arrow()}`)}${link('arena'+previewSuffix(preview),`<span class="feature-orb">${icon('swords')}</span><span><small>HEAD-TO-HEAD PROGRESSION</small><strong>Guild Battle</strong></span>${arrow()}`)}</div>`};
const progressionArenaPage=arenaPage;
arenaPage=function(tab='overview'){const html=progressionArenaPage(tab);return html+`<section class="battle-upgrade-path"><div><span class="page-eyebrow">A CHALLENGE. A CHECKPOINT. A NEW CHAPTER.</span><h2>Progress as a guild.</h2><p>Head-to-head results feed a separate guild progression journey, alongside the season leaderboard.</p></div><div class="battle-upgrade-stages"><span>${icon('swords')}<strong>Challenge</strong><small>Two guilds meet</small></span><i></i><span>${icon('shield')}<strong>Review</strong><small>Verify the result</small></span><i></i><span>${icon('trophy')}<strong>Progress</strong><small>Guild upgrade concept</small></span></div><div class="battle-upgrade-foot"><span>Upgrade thresholds, rewards and tier rules remain adjustable design parameters.</span><button class="secondary" data-preview-battle-result>Preview the next chapter ${arrow()}</button></div></section>`};

const seasonGuildOverview=profileOverview;
profileOverview=function(g){const c=captains.find(c=>c.guild===g.id);const leader=c?`<section class="guild-leader-intro"><span class="captain-avatar ${c.color}">${c.name.slice(0,1)}</span><div><small>MEET THE GUILD LEADER</small><h3>${c.name}</h3><p>${c.style} · Understand the strategy before choosing to copy.</p></div><div>${link('leaders/'+c.id,'View leader performance '+arrow(),'secondary button')}${canCopyGuildLeader(c)?link('my-guild/copy','Open member copy workspace '+arrow(),'text-button'):'<span class="member-copy-locked">'+icon('lock')+' Copy access is for this guild’s members</span>'}</div></section>`:'';return leader+seasonGuildOverview(g)};

// A single persistent, non-modal chat dock survives navigation across the site.
const chatRoot=document.createElement('div');chatRoot.id='persistent-guild-chat';document.body.appendChild(chatRoot);
function currentChatId(){return seasonUI.chatGuild||state.membership?.id||'lounge'}
function chatRoom(id){return id==='lounge'?{id:'lounge',name:'Season lounge',announcement:'Welcome to the Guild Open lounge. Different teams, shared respect. This is a local conversation preview.'}:guildById(id)||guildById('unisat')}
function openGuildChat(id){captureChatDraft();if(id)seasonUI.chatGuild=id;seasonUI.chatReturnFocus=document.activeElement;seasonUI.chatOpen=true;mountChat(false);setTimeout(()=>$('#dock-chat-message')?.focus(),0)}
function closeGuildChat(){captureChatDraft();seasonUI.chatOpen=false;mountChat();seasonUI.chatReturnFocus?.focus?.({preventScroll:true})}
function captureChatDraft(){const box=$('#dock-chat-message');if(box)seasonUI.chatDrafts[currentChatId()]=box.value}
function mountChat(preserveDraft=true){if(preserveDraft)captureChatDraft();const id=currentChatId(),g=chatRoom(id),local=state.forums[id]||[];chatRoot.innerHTML=`${seasonUI.chatOpen?`<section id="guild-chat-window" class="guild-chat-dock" role="dialog" aria-label="Guild chat" aria-modal="false"><header class="dock-header"><div><span class="dock-header-icon">${icon('chat')}</span><div><strong>Guild chat</strong><small>YOUR COMMUNITY, ALWAYS CLOSE</small></div></div><div><button class="dock-members-toggle ${seasonUI.chatMembers?'selected':''}" data-dock-members aria-label="${seasonUI.chatMembers?'Show messages':'Show members'}">${icon('users')}</button><button data-close-chat aria-label="Minimize guild chat">−</button></div></header><div class="dock-channel"><label class="sr-only" for="dock-room">Chat room</label><select id="dock-room"><option value="lounge" ${id==='lounge'?'selected':''}># Season lounge</option>${id!=='lounge'&&id!==(state.membership?.id||'unisat')?`<option value="${id}" selected># ${escapeHtml(g.name)} · Preview room</option>`:''}${state.membership?`<option value="${state.membership.id}" ${id===state.membership.id?'selected':''}># ${escapeHtml(guildById(state.membership.id)?.name||'My Guild')}</option>`:`<option value="unisat" ${id==='unisat'?'selected':''}># UniSat · Preview room</option>`}</select><span>LOCAL DEMO</span></div><div class="dock-pin">${icon('pin')}<p>${escapeHtml(g.announcement||'Share your perspective, support the team and keep the conversation thoughtful.')}</p></div>${seasonUI.chatMembers?`<div class="dock-member-view"><h3>${id==='lounge'?'The competition community':'Your trading circle'}</h3><p>${id==='lounge'?'Sample guild representatives':'Sample roster · Membership is not a live feed'}</p>${(id==='lounge'?captains.map(c=>({name:c.name,initial:c.name.slice(0,1),role:guildById(c.guild).name})):roster(g)).map((m,i)=>`<div><span class="avatar avatar-${i%4}">${escapeHtml(m.initial)}</span><span><strong>${escapeHtml(m.name)}</strong><small>${m.role}</small></span></div>`).join('')}</div>`:`<div class="dock-messages" id="dock-messages"><div class="dock-chat-date">A SHARED SPACE · DEMONSTRATION</div><div class="dock-message"><span class="avatar avatar-1">${id==='lounge'?'X':'L'}</span><div><div><strong>${id==='lounge'?'Guild Open host':'Guild leadership'}</strong><small>SAMPLE MESSAGE</small></div><p>${id==='lounge'?'A place to connect across trading circles. Which part of the season are you exploring?':'Welcome to the team. Share your perspective, coordinate a mission or ask a question.'}</p></div></div>${local.map(m=>`<div class="dock-message self"><div><div><strong>${escapeHtml(m.name)}</strong><small>${escapeHtml(m.time)} · LOCAL</small></div><p>${escapeHtml(m.text).replace(/\n/g,'<br>')}</p></div></div>`).join('')}</div><form id="dock-chat-form" class="dock-composer"><label class="sr-only" for="dock-chat-message">Your local chat message</label><textarea id="dock-chat-message" name="message" rows="1" maxlength="2000" required placeholder="Share a thought…">${escapeHtml(seasonUI.chatDrafts[id]||'')}</textarea><button type="submit" aria-label="Save chat message locally">${icon('send')}</button></form>`}<div class="dock-local-note">${icon('lock')} Saved on this browser. Not sent to other people.</div></section>`:''}<button class="guild-chat-launcher ${seasonUI.chatOpen?'open':''}" aria-expanded="${seasonUI.chatOpen}" aria-controls="guild-chat-window" data-toggle-chat><span>${icon(seasonUI.chatOpen?'chevron':'chat')}</span><div><strong>${seasonUI.chatOpen?'Minimize chat':'Guild chat'}</strong><small>${seasonUI.chatOpen?'Stay in the flow':state.membership?'Your team, one click away':'Community preview'}</small></div>${seasonUI.chatOpen?'':`<i>${icon('chevron')}</i>`}</button>`;if(seasonUI.chatOpen&&!seasonUI.chatMembers){const m=$('#dock-messages');m.scrollTop=m.scrollHeight}}
const classicRoute=renderRoute;
renderRoute=function(scroll=true){captureChatDraft();classicRoute(scroll);if(!routePath){$('#season-home').innerHTML=seasonHome()}if(routePath==='leaders')updateLeaders();if(routePath.startsWith('forum')){openGuildChat(routePath.split('/')[1]);location.hash=state.membership?'#/my-guild':'#/'}mountChat()};
// Retain legacy widgets for shared demo-state rendering; the new home owns the presentation.
const legacyHome=document.createElement('div');legacyHome.id='legacy-guild-home';legacyHome.hidden=true;while($('#overview').firstChild)legacyHome.appendChild($('#overview').firstChild);$('#overview').appendChild(legacyHome);const seasonHomeRoot=document.createElement('div');seasonHomeRoot.id='season-home';$('#overview').prepend(seasonHomeRoot);
// Treat forum links as chat actions, without taking people away from their current task.
document.addEventListener('click',e=>{const a=e.target.closest('a[href*="#/forum"]');if(a){e.preventDefault();e.stopImmediatePropagation();const id=a.getAttribute('href').split('#/forum/')[1]?.split('?')[0];openGuildChat(id)}},true);
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.hasAttribute('data-toggle-chat')){seasonUI.chatOpen?closeGuildChat():openGuildChat()}if(b.hasAttribute('data-close-chat'))closeGuildChat();if(b.hasAttribute('data-dock-members')){captureChatDraft();seasonUI.chatMembers=!seasonUI.chatMembers;mountChat()}if(b.hasAttribute('data-preview-battle-result'))open(`<div class="welcome-modal"><div class="modal-eyebrow">POST-BATTLE DESIGN PREVIEW</div><span class="copy-ready-icon">${icon('trophy')}</span><h2>A shared result.<br>A new chapter.</h2><p>This state connects a verified head-to-head result to guild progression. It does not change the main season standings or award an actual tier.</p><span class="member-pill">${icon('shield')} Progression outcome · Parameters pending</span><button class="primary" data-close-flow>Back to the challenge</button></div>`);if(b.dataset.openChat){openGuildChat(b.dataset.openChat)}if(b.dataset.seasonMetric){seasonUI.metric=b.dataset.seasonMetric;renderRoute(false)}if(b.dataset.leaderFilter){seasonUI.leaderFilter=b.dataset.leaderFilter;document.querySelectorAll('[data-leader-filter]').forEach(el=>el.classList.toggle('selected',el===b));updateLeaders()}if(b.hasAttribute('data-reset-leaders')){seasonUI.leaderFilter='all';seasonUI.leaderSearch='';renderRoute(false)}if(b.dataset.resultStage){seasonUI.stage=b.dataset.resultStage;renderRoute(false)}if(b.dataset.startCopy)startCopy(b.dataset.startCopy);if(b.dataset.copyAmount){$('#copy-allocation').value=b.dataset.copyAmount;captureCopyDraft();document.querySelectorAll('[data-copy-amount]').forEach(el=>el.classList.toggle('selected',el===b))}if(b.hasAttribute('data-copy-next')){if(!canCopyGuildLeader(leaderById(copyDraft?.leader))){showGuildCopyGate(leaderById(copyDraft?.leader));return;}const f=$('#copy-setup-form');if(!f.reportValidity())return;captureCopyDraft();const v=copyStep===1?Number(copyDraft.allocation):Number(copyDraft.orderCap),loss=Number(copyDraft.stopLoss);if(!Number.isFinite(v)||v<=0||copyStep===2&&(v>100||loss<=0||loss>100)){toast('Enter a valid allocation and percentage limits.');return}copyStep++;renderCopySetup()}if(b.hasAttribute('data-copy-prev')){captureCopyDraft();copyStep=Math.max(1,copyStep-1);renderCopySetup()}if(b.dataset.planToggle){const p=state.copyPlans.find(p=>p.id===b.dataset.planToggle);if(p&&p.status!=='stopped'){if(p.status==='paused'&&!canCopyGuildLeader(leaderById(p.leader))){showGuildCopyGate(leaderById(p.leader));return;}p.status=p.status==='paused'?'running':'paused';save();toast(p.status==='paused'?'Demo plan paused. No real positions are affected.':'Demo plan resumed. No trades are executed.')}}if(b.dataset.planStop){const p=state.copyPlans.find(p=>p.id===b.dataset.planStop);if(p)open(`<div class="modal-eyebrow">YOUR PLAN. YOUR CONTROL.</div><h2>Stop this demo plan?</h2><p>The simulated plan will move to Stopped. No positions or funds exist in this prototype, so no closing trade is sent.</p><div class="modal-actions"><button class="secondary" data-close-flow>Keep plan</button><button class="secondary danger" data-confirm-plan-stop="${p.id}">Stop demo plan</button></div>`)}if(b.dataset.confirmPlanStop){const p=state.copyPlans.find(p=>p.id===b.dataset.confirmPlanStop);if(p){p.status='stopped';close();save();toast('Demo plan stopped.')}}});
document.addEventListener('input',e=>{if(e.target.id==='season-rank-search'){ui.rankQuery=e.target.value;$('#season-standings').innerHTML=seasonRankRows();const count=$('#season-result-count');if(count)count.textContent=`${$('#season-standings').querySelectorAll('.table-guild').length} guilds shown`}if(e.target.id==='leader-search'){seasonUI.leaderSearch=e.target.value;updateLeaders()}if(e.target.id==='dock-chat-message')seasonUI.chatDrafts[currentChatId()]=e.target.value});
document.addEventListener('change',e=>{if(e.target.id==='dock-room'){captureChatDraft();seasonUI.chatGuild=e.target.value;mountChat(false)}});
document.addEventListener('submit',e=>{const f=e.target;if(f.id==='copy-setup-form'){e.preventDefault();if(!canCopyGuildLeader(leaderById(copyDraft?.leader))){showGuildCopyGate(leaderById(copyDraft?.leader));return;}if(copyStep<3){f.querySelector('[data-copy-next]')?.click();return}if(!f.reportValidity())return;if(state.copyPlans.some(p=>p.leader===copyDraft.leader&&p.status!=='stopped')){navigate('my-guild/copy');toast('A demo plan already exists for your guild leader.');return;}const id='copy-'+Date.now();state.copyPlans.push({...copyDraft,id,status:'running',created:new Date().toISOString()});state.wallet=true;save();open(`<div class="welcome-modal"><div class="modal-eyebrow">A CLEAR PLAN. YOUR OWN CONTROL.</div><span class="copy-ready-icon">${icon('copy')}</span><h2>Your demo plan<br>is ready.</h2><p>Your allocation and limits are saved on this browser. No funds have moved and no orders will be opened.</p><span class="member-pill">${icon('check')} Simulated plan · Not trading</span><button class="primary" data-open-copy-plans>Manage my demo plan ${arrow()}</button></div>`)}if(f.id==='season-entry-form'){e.preventDefault();if(!f.reportValidity())return;const id=f.dataset.id;if(state.membership?.id!==id||state.membership?.role!=='owner'){toast('Demo team entry is managed by the guild leader.');return}state.seasonEntries[id]={reviewedBy:state.membership.name,members:guildById(id).members,created:new Date().toISOString()};save();toast('Demo team entry confirmed on this browser.')}if(f.id==='dock-chat-form'){e.preventDefault();const id=currentChatId(),text=$('#dock-chat-message').value.trim();if(!text)return;if(!state.forums[id])state.forums[id]=[];state.forums[id].push({text:text.slice(0,2000),name:state.profileName||state.membership?.name||'Demo Trader',time:new Date().toLocaleTimeString('en-GB',{hour:'2-digit',minute:'2-digit',timeZone:'Asia/Hong_Kong'})});if(state.forums[id].length>100)state.forums[id].shift();seasonUI.chatDrafts[id]='';$('#dock-chat-message').value='';save();mountChat();$('#dock-chat-message').focus()}});
document.addEventListener('click',e=>{if(e.target.closest('[data-open-copy-plans]'))navigate('my-guild/copy')});
document.addEventListener('keydown',e=>{if(e.target.id==='dock-chat-message'&&e.key==='Enter'&&!e.shiftKey&&!e.isComposing){e.preventDefault();e.target.form.requestSubmit()}if(e.key==='Escape'&&seasonUI.chatOpen&&!modal.open){e.preventDefault();closeGuildChat()}});
const seasonBaseRender=render;render=function(){reconcileGuildCopyPlans();seasonBaseRender();if(!routePath&&$('#season-home'))$('#season-home').innerHTML=seasonHome();mountChat()};
// Initial rendering follows the guild-member access definitions below.
function strategyCurve(c){const pattern=[0,.1,.06,.22,.18,.35,.27,.44,.38,.56,.5,.68,.62,.82,1],max=Math.ceil((100+c.roi)/10)*10,min=95;const points=pattern.map((v,i)=>`${(i*600/(pattern.length-1)).toFixed(1)},${(145-(100+v*c.roi-min)/(max-min)*130).toFixed(1)}`).join(' ');return `<div class="volume-chart"><div class="chart-legend"><span><i></i> INDEXED EQUITY · BASE 100</span><small>30-day illustration</small></div><div class="chart-canvas"><div class="chart-y"><span>${max}</span><span>${Math.round((max+100)/2)}</span><span>100</span><span>${min}</span></div><svg viewBox="0 0 600 160" role="img" aria-label="Illustrative equity curve from 100 to ${(100+c.roi).toFixed(1)}" preserveAspectRatio="none"><defs><linearGradient id="strategyfill" x1="0" x2="0" y1="0" y2="1"><stop offset="0%" stop-color="#368ace" stop-opacity=".25"/><stop offset="100%" stop-color="#368ace" stop-opacity="0"/></linearGradient></defs><path d="M0 25H600M0 65H600M0 105H600M0 145H600" stroke="#243c54" stroke-dasharray="3 6" stroke-width="1"/><polygon points="0,160 ${points} 600,160" fill="url(#strategyfill)" stroke="none"/><polyline points="${points}" stroke="#65b1ea" fill="none" stroke-width="2.3" vector-effect="non-scaling-stroke"/></svg></div><div class="chart-x"><span>DAY 01</span><span>DAY 07</span><span>DAY 14</span><span>DAY 21</span><span>DAY 30</span></div></div>`}
function teamSeasonCurve(g){const total=seasonVolume(g),pattern=[0,.03,.05,.09,.13,.2,.27,.32,.41,.48,.55,.65,.72,.81,.88,1];const max=total?total*1.08:1;const points=pattern.map((v,i)=>`${(600*i/(pattern.length-1)).toFixed(1)},${(145-v*total/max*135).toFixed(1)}`).join(' ');return `<div class="volume-chart"><div class="chart-legend"><span><i></i> CUMULATIVE TEAM VOLUME</span><small>Season illustration</small></div><div class="chart-canvas"><div class="chart-y"><span>${total?numberCompact(max):'—'}</span><span>${total?numberCompact(max*2/3):'—'}</span><span>${total?numberCompact(max/3):'—'}</span><span>$0</span></div><svg viewBox="0 0 600 160" role="img" aria-label="Illustrative cumulative guild volume ending at ${numberCompact(total)}" preserveAspectRatio="none"><defs><linearGradient id="teamseasonfill" x1="0" x2="0" y1="0" y2="1"><stop offset="0%" stop-color="#2689d1" stop-opacity=".25"/><stop offset="100%" stop-color="#2689d1" stop-opacity="0"/></linearGradient></defs><path d="M0 15H600M0 58H600M0 101H600M0 145H600" stroke="#233c55" stroke-dasharray="3 6" stroke-width="1"/><polygon points="0,160 ${points} 600,160" fill="url(#teamseasonfill)" stroke="none"/><polyline points="${points}" fill="none" stroke="#4aa3e6" stroke-width="2.3" vector-effect="non-scaling-stroke"/></svg></div><div class="chart-x"><span>ENTRY</span><span>CHECKPOINT 01</span><span>CHECKPOINT 02</span><span>CURRENT</span></div></div>`}
// Public performance is discovery. Copy access belongs to the current guild's members.
function canCopyGuildLeader(c){return !!c&&!!state.membership&&state.membership.id===c.guild&&state.membership.role==='member'}
function publicLeaderAccess(c){const g=guildById(c.guild);if(canCopyGuildLeader(c))return `${link('my-guild/copy','Open my guild copy workspace '+arrow(),'primary button')}<small>Member-only access · ${escapeHtml(g.name)}</small>`;return `${link('guild/'+g.id,'Explore '+escapeHtml(g.name)+' '+arrow(),'primary button')}<small>${icon('lock')} Performance is public. Copying is for this guild’s members.</small>`}
function showGuildCopyGate(c){if(!c){toast('This guild leader strategy is unavailable.');return}const g=guildById(c.guild),ownLeader=state.membership?.id===c.guild&&state.membership?.role==='owner';open(`<div class="guild-copy-gate"><span>${icon('lock')}</span><div class="modal-eyebrow">A GUILD MEMBER BENEFIT</div><h2>${ownLeader?'This is your leadership profile.':'Copy your own guild leader.'}</h2><p>${ownLeader?'Guild leaders publish their performance for everyone to see. Copying is a feature for their guild members.':`Everyone can view ${escapeHtml(c.name)}’s performance. To configure copying, you must be a member of ${escapeHtml(g.name)}.`}</p>${state.membership&&state.membership.id!==c.guild?`<div class="notice">You currently belong to ${escapeHtml(guildById(state.membership.id)?.name||'another guild')}. Copy access is limited to your own guild leader.</div>`:''}<div class="modal-actions"><button class="secondary" data-close-flow>Keep exploring</button>${link('guild/'+g.id,'View guild '+arrow(),'primary button')}</div></div>`)}
function reconcileGuildCopyPlans(){let changed=false;for(const p of state.copyPlans){if(p.status==='running'&&!canCopyGuildLeader(leaderById(p.leader))){p.status='paused';p.pauseReason='membership';changed=true}}if(changed){try{localStorage.setItem('xox-guild-demo-v1',JSON.stringify(state))}catch{}}return changed}
const membershipBaseRoute=renderRoute;
renderRoute=function(scroll=true){reconcileGuildCopyPlans();membershipBaseRoute(scroll)};
copyPlansPage=function(preview=false){const member=state.membership,c=member&&captains.find(c=>c.guild===member.id),eligible=!preview&&canCopyGuildLeader(c);const active=state.copyPlans.filter(p=>p.status!=='stopped'&&canCopyGuildLeader(leaderById(p.leader)));return breadcrumb(`${link('my-guild'+previewSuffix(preview),'My Guild')}<span>/</span>Guild leader copy`)+heading('FOR YOUR GUILD. BY YOUR CHOICE.','YOUR GUILD LEADER.<br><span>YOUR OWN LIMITS.</span>','Leader performance is public. Copy access belongs to members of the same guild; joining never activates copying automatically.')+`<div class="member-copy-access ${eligible?'eligible':''}"><span>${icon(eligible?'shield':'lock')}</span><div><small>${eligible?'GUILD MEMBERSHIP CONFIRMED':'GUILD MEMBER ACCESS'}</small><h2>${eligible?'Copy '+c.name:preview?'Member workspace preview':!member?'Find your trading circle first':member.role==='owner'?'Your team follows your perspective':'Your guild leader has no connected sample strategy yet'}</h2><p>${eligible?`You’re a member of ${escapeHtml(guildById(c.guild).name)}. Review the strategy and choose whether to create a local demo plan.`:preview?'Viewing this sample dashboard does not grant membership or copy access.':!member?'You can view every leader’s performance. Join a guild to access that guild leader’s copy feature.':member.role==='owner'?'This is a member feature. Leaders do not copy their own strategy.':'Performance and copying can become available here when your guild leader has a strategy.'}</p></div>${eligible?`<button class="primary" data-start-copy="${c.id}">Configure guild leader copy ${icon('copy')}</button>`:link(!member||preview?'discover':member.role==='owner'?'my-guild':'leaders',!member||preview?'Explore guilds '+arrow():member.role==='owner'?'Open team dashboard '+arrow():'View public leader performance '+arrow(),'secondary button')}</div><div class="copy-plans-summary"><div><small>ELIGIBLE DEMO ALLOCATION</small><strong>${numberCompact(active.reduce((sum,p)=>sum+Number(p.allocation),0))}</strong></div><div><small>ELIGIBLE DEMO PLANS</small><strong>${active.length}</strong></div><div><small>ACTUAL OPENED POSITIONS</small><strong>0</strong></div><div><small>REAL FUNDS ALLOCATED</small><strong>$0.00</strong></div></div><div class="copy-plan-list">${state.copyPlans.length?state.copyPlans.filter(p=>leaderById(p.leader)).map(p=>{const leader=leaderById(p.leader),allowed=canCopyGuildLeader(leader);return `<article class="workspace-panel copy-plan"><div class="copy-plan-top"><div><span class="captain-avatar ${leader.color}">${leader.name.slice(0,1)}</span><div><h2>${leader.name}</h2><p>${guildById(leader.guild).name} · Guild-member demo plan</p></div></div>${progressPill(p.status==='running'?'blue':p.status==='paused'?'amber':'gray',p.status==='running'?'SIMULATION READY':p.status==='paused'?'PAUSED':'STOPPED')}</div><div class="copy-plan-values"><div><span>Allocation</span><strong>${Number(p.allocation).toLocaleString()} USDT</strong></div><div><span>Per-position cap</span><strong>${p.orderCap}% <em>· ${(p.allocation*p.orderCap/100).toFixed(2)} USDT</em></strong></div><div><span>Loss threshold</span><strong>${p.stopLoss}%</strong></div><div><span>Leverage cap</span><strong>${p.leverage}×</strong></div></div>${p.pauseReason==='membership'&&!allowed?'<div class="copy-membership-paused">'+icon('lock')+' Paused: your current membership does not grant access to this guild leader.</div>':''}<div class="copy-plan-foot"><span>${p.status==='stopped'?'Stopped local demo plan. No funds or positions existed.':allowed?'Local simulation only. No orders, trades or P&L are generated.':'Historical demo plan. Copy access requires membership in this leader’s guild.'}</span><div>${link('leaders/'+leader.id,'View performance '+arrow(),'text-button')}${p.status!=='stopped'?`${allowed?`<button class="secondary" data-plan-toggle="${p.id}">${icon(p.status==='paused'?'arrow':'pause')}${p.status==='paused'?'Resume demo':'Pause demo'}</button>`:''}<button class="secondary danger" data-plan-stop="${p.id}">Stop plan</button>`:''}</div></div></article>`}).join(''):`<div class="page-empty">${icon('copy')}<h2>${eligible?'Follow your leader, on your terms.':'Performance is open. Membership unlocks copying.'}</h2><p>${eligible?'Review the strategy, set your allocation and define your own limits before confirming.':'Public leader results help you find the right guild. Only that guild’s members can configure a copy plan.'}</p>${eligible?link('leaders/'+c.id,'Review your leader’s strategy '+arrow(),'primary button'):link('leaders','View leader performance '+arrow(),'secondary button')}</div>`}</div><div class="copy-risk-note">${icon('info')} Copying is optional and member-only. Leaving or changing guild pauses ineligible local demo plans; resuming requires valid membership. Copied-volume competition attribution remains a rule to be designed.</div>`};
// Initial rendering is owned by the Guild World entry module.
